  stockVarianceIntro:
    '판매×레시피(BOM)로 계산한 이론 원재료 소진과, 재고등식(기초+입고−출고−기말)으로 역산한 실제 소진을 품목별로 비교합니다.\n실제 열은 POS 자동차감이 아니라 재고 변동 전체입니다. Usage·조정·POS 열은 설명용 분해입니다.\n차이 = 실제 − 이론 (양수면 이론보다 더 소진). BOM 정확도와 기말 실사가 있어야 의미가 있습니다.',
