  stockDailyMatrixMobileTitle: '품목 카드',
  stockDailyMatrixRpcHint: 'DB 집계(RPC) 사용',
  helpSum_admin_stock:
    '매장·본사 창고 재고를 조회·조정하고, 본사 일별 입출고 탭에서 S&J 창고 입고·매장 출고·잔량·인보이스를 한 화면에서 볼 수 있습니다.',
  helpHow_admin_stock:
    '① 재고 목록: 매장·기준일을 고른 뒤 조회합니다. 재고금액은 소수 둘째 자리(0.01바트)로, 손익 재고와 같은 기준입니다. 본사·매장 매니저는 재고 조정이 가능합니다. 조정은 선택한 기준일로 저장되므로 월말 실사는 해당 날짜를 고른 뒤 Adjust 하세요. 실사 기한(말일 전후)에는 안내 배너가 뜹니다. 매장 운영 허브의 미실사 매장에서 들어오면 매장·기말이 미리 채워집니다.\n② 발주 도움: 기간 사용량·보충 제안을 확인합니다(자동 발주 아님).\n③ 본사 일별 입출고(본사 권한): 기간·창고·매장·보기 모드(상세/일합계/매장피벗)로 입출고 매트릭스를 보고, OUT 셀·인보이스에서 출고 이력·인쇄로 연결할 수 있습니다.\n④ 엑셀(XLSX)로 Daily Stock Report 형식보내기를 할 수 있습니다.',
  helpSum_admin_outbound:
    '본사 창고에서 매장·판매처로 출고합니다. 강제출고는 대기 목록을 한 번에 확정하면 같은 출고일·출고처·참조번호가 IVF 한 장으로 묶이고, 주문 출고는 주문당 IV 한 장입니다. 세금계산서·e-Tax·วางบิล은 배송완료(일부 포함)만 대상이며, 이력 합계는 청구액과 출고 전체를 구분합니다.',
  helpHow_admin_outbound:
    '① 출고 입력: 날짜·배송일·출고처·참조번호(필수)를 넣고 품목을 담은 뒤 확정합니다. 같은 참조번호·출고처·날짜는 Invoice 인쇄 시 한 장입니다.\n② 이력: 기간 조회 후 Invoice 인쇄·삭제·엑셀을 사용합니다. 우상단 초록 합계는 청구(배송완료) VAT이고, 아래 회색은 출고 전체(배송중 포함)입니다. 배송중 건은 ใบกำกับ/e-Tax가 막힙니다. 강제출고 행을 펼치면 묶인 품목을 볼 수 있습니다.\n③ 권한에 따라 일부 탭이 보이지 않을 수 있습니다.',
  helpSum_admin_notices:
    '직원·매장 공지를 작성·발송하고, 발송 내역·미확인자·자동 알림(업무일지·월말 재고조사 등)을 관리합니다.',
  helpHow_admin_notices:
    '① 새 공지: 대상·미리보기 확인 후 발송합니다.\n② 발송 내역: 확인율·재알림·수정을 씁니다.\n③ 미확인자: 미확인 집계·수당 제외를 처리합니다.\n④ 자동 알림: 업무일지와 월말 실사(기한 시작일·말일 다음날, 미완료 매장 매니저만)를 켜고,「반복 공지 추가」로 규칙을 저장합니다.',
  stockReorderIntro:
    '본사(Office·입고등록)를 고르면 기간 출고(Outbound·강제출고) 합계, 매장을 고르면 사용 확정(Usage)만 집계합니다. 보충 제안 = max(0, 기간 소모 + 안전재고 − 현재고)이며, 자동으로 발주서를 만들지는 않습니다.',
