  helpHow_admin_hr_policies:
    '① 제목·첨부(또는 본문)·수신 대상(전체/오피스/매장/개인)을 입력한 뒤 저장합니다. 저장하면 대상 직원 화면에도 바로 보입니다.\n② 규정 목록에서 대상 구분 필터·「등록 내용 보기」·열람 상세를 확인합니다.\n③ 공지 안내가 필요하면「대상·배포(공지)」로 보냅니다. 초안(미게시)은 목록에서 비활성화할 수 있습니다.',
  helpSum_admin_hr:
    '인사 관리 허브 — 휴가·근태 미승인(사이드바 배지는 GPS·강제퇴근 등 미처리·최근 휴가 대기만), 이번 주 인사 일정, 급여·직원·규정 메뉴로 바로 이동합니다.',
  helpHow_admin_hr:
    '① 상단 KPI·사이드바 배지는 「아직 아무도 승인하지 않은」 건만 셉니다(근태는 위치미확인·강제퇴근 등, 휴가는 최근 휴가일 대기).\n② 각 카드의 바로가기로 휴가·근태·캘린더·급여 화면으로 이동합니다.\n③ 상단 서브내비로 직원·규정·캘린더·근태·휴가·급여를 오갑니다.',
  helpSum_admin_attendance:
    '출퇴근 기록 조회·승인, 지각·조퇴·연장 조정, 당일 실시간 근무, 주간 스케줄 조회·작성을 한 화면에서 처리합니다. 사이드바 배지는 GPS·강제퇴근 등 미승인만 표시합니다.',
  helpHow_admin_attendance:
    '① [근태 기록/승인]: 기간·매장·직원·상태로 조회 후 승인·조정합니다. 야간(22:00–08:00)은 익일 08시대 퇴근까지 출근일로 묶입니다.\n② [당일 실시간]: 매장을 고른 뒤 검색을 누르면 시간대별 근무·휴게 도트가 나옵니다. 휴대폰에서는 표를 위·아래·좌우로 밀어 보세요.\n③ [스케줄 조회]·[스케줄 작성]: 주간 근무표를 확인·편집합니다. 일괄입력 휴게 시작은 시간표 범위(기본 06:00~31:00, 자정 이후는 24:00~·익일 07:00은 31:00)에서 고릅니다. 저장 전에 같은 날 동일 직원 중복을 검사하며, 오류가 나도 기존 표는 지우지 않습니다.\n④ 사이드바 숫자는 위치미확인·강제퇴근처럼 아직 승인 안 된 건만이며, 지각·연장·조퇴 조정은 이 화면에서 기간 조회해 처리합니다.\n⑤ [도움말] 탭에서 승인·조정·연장 규칙을 확인합니다.\n⑥ 휴게 열 옆에 예정 휴게와 실제 휴게(시작–종료)가 보입니다. 예정 구간 밖에서 휴게를 시작하면 빨간색입니다. 스케줄 조회·작성에는 직원별 마지막 수정자와 시간이 보이며, 그 줄을 누르면 그 주에 바뀐 칸이 열립니다.',
  helpSum_admin_leave:
    '휴가 신청 승인·반려와 기간별 연차·병가 등 사용·잔여 통계를 관리합니다. 「승인자」탭에서 전체 승인자·매장 승인자를 지정할 수 있습니다. 통계 기본은 재직 직원만 보이며, 사이드바 배지는 최근 휴가일 기준 미승인만 표시합니다.',
  helpHow_admin_leave:
    '① [승인]: 대기 목록에서 증명서 확인 후 승인·반려합니다.\n② [통계]: 기간·매장별 사용·잔여 연차를 조회합니다. 기본은 재직 직원만 보이며, 검색에서 퇴사·전체로 바꿀 수 있습니다.\n③ [승인자]: 전체 승인자(모든 매장)와 매장별 승인자를 지정합니다. 매장에 한 명이라도 지정되면 그 목록(+전체 승인자·Director)만 승인합니다. 미지정 매장은 점장·가맹점주 폴백입니다.\n④ 급여 관리에서 월별로 링크해 들어올 수 있습니다.\n⑤ 사이드바 배지는 최근 30일(휴가일)~미래 미승인만 집계합니다.',
  helpSum_admin_hr_calendar:
    '재직 직원의 생일·입사·N년·퇴사일을 월별 캘린더와 목록으로 확인합니다.',
  helpHow_admin_hr_calendar:
    '① 월·매장·유형 필터로 일정을 좁힙니다.\n② 캘린더·목록에서 행을 클릭하면 직원 관리로 이동합니다.\n③ 생일·입사기념 등을 매장 운영 일정과 함께 활용합니다.',
  helpSum_admin_payroll:
    '급여 계산·DB 저장, 명세서 조회·공지, 급여 변경 이력, 공휴일·규칙, 도움말을 한 화면에서 다룹니다.',
  helpHow_admin_payroll:
    '① [급여 계산]: 월을 고르면 근무기간·지급일이 아래에 보입니다 → 계산 실행 → 확인 후 DB 저장. 기간·지급일은 [급여 규칙]에서 바꿀 수 있습니다(기본 1일~말일, 다음 달 5일). 손익 인건비는 이 월 기준입니다.\n② [명세서]: 저장된 급여 조회(이름·닉네임)·직원 공지·엑셀 내보내기.\n③ [도움말] 탭에서 지각·조퇴·OT·공휴일 반영 규칙을 확인합니다.\n④ 오피스(본사) 급여를 확정 저장하면 지출관리에는 직원별이 아니라 매장·월 합산 1건만 올라갑니다(개인 명세는 급여 화면·오피스 급여 담당만).',
  adminHrCalendar: '인사 캘린더',
