  emp_sso_exempt_hint:
    '미가입·프리랜서·서류 미비 시 체크. 급여 계산에서 SSO를 0으로 하고 원천세 3%를 공제합니다. 급여 원천은 ภ.ง.ด.1(PND1)로 신고합니다. 개인 용역비(지출)만 PND3입니다.',
