  emp_job_edit_eval_note:
    '「주방」등 한글 표기는 급여에서 주방으로 볼 수 있으나, 직원 평가 목록에는 영문 Kitchen·Service가 기준입니다. 혼동을 피하려면 Kitchen·Service를 사용하세요.',
