    '※ 매장을 고르면 그 매장 입고·매입 지출발생과 그 매장 통장만으로 거래처별 미지급을 계산합니다. 과거에 매입 대금으로 등록한 지출 발생도 그 거래처 잔액에 청구로 포함됩니다. 입고등록(본사 창고)은 본사(CM Office) 장부입니다.  매입채무는 입고(매입 관리) 또는 지출 발생등록 시 발생합니다. 통장에서 「매입 대금」으로 저장하고 거래처를 고르면 그 거래처 미지급에서 지급으로 차감됩니다. 입고 건과 짝을 맞추려면 「지출관리 연결」을 사용하세요. 매입 대금 행의 원천세는 지급 금액(실이체)과 따로 빠져 거래처 잔액을 줄이고 원천세 원장에 남습니다. 입고 행은 같은 통장의 지급과 원천세를 합쳐 입고 금액과 같으면 지급으로 표시됩니다. 인보이스 열은 ภ.พ.30(부가세) 참고용이며 지급 여부와 무관합니다.',
