  mmBridgeContribPct: '기여율',
  adminBalanceSheet: '재무상태표',
  adminFinancialStatements: '기업회계',
  helpSum_admin_financial_statements:
    '기업회계(경영) 손익입니다. 세무 장부와 금액이 달라도 됩니다. 손익·재무상태표·마진 등을 매장·기간으로 조회합니다. 재무상태표 부채에 차입금(2150), 자산에 대여금(1150)이 포함됩니다. 급여(5310)는 실지급일이 아니라 급여 월(주기 라벨)에 반영됩니다. 승인된 회계 PO(로열티·배달 GP·Grab GP)는 매장 비용·본사(발행) 매출에 반영되며, VAT 포함/제외 토글에 맞춰 청구 total/subtotal을 씁니다. VAT 포함 보기에서 PP.30 납부는 세금 귀속월 비용으로 들어갑니다(미포함 보기·PND는 제외).',
  helpHow_admin_financial_statements:
    '① 매장·시작월·종료월을 고른 뒤 검색합니다. 월·매장만 바꾸면 다시 검색하기 전에는 손익·재무상태·대조·마진 모두 이전 조회 결과가 유지됩니다.\n② 손익에서 VAT 포함/제외를 전환하면 매출·매입·재고와 함께 가맹 청구(승인 PO) 금액도 맞춰집니다. 금액은 0.01바트(소수 둘째 자리)까지 표시합니다. 포함 보기만 PP.30 납부(세금 귀속월, 통장 출금일 아님)를 비용에 넣습니다.\n③ 로열티·배달/Grab GP는 PO 관리에서 비율 입력 후 회계 PO를 승인해야 손익에 전기됩니다(Draft·플랫폼 5528 수수료와 별개).\n④ 수동 매출·기초재고는 한 달만 선택해 입력·저장하고, 여러 달 보기에서는 월별로 저장된 값이 반영됩니다.\n⑤ 다른 메뉴·하위 탭을 갔다 와도 검색 조건·결과는 유지됩니다.\n⑥ 급여는 지급일이 아니라 급여 월 손익에 들어갑니다. 확정 급여가 있으면 통장·패티 급여성 출금은 이중 방지로 제외합니다.',
  adminChartOfAccounts: '계정과목표(COA)',
  adminAccountingCompliance: '회계·태국 신고',
