    '지각·조퇴·OT는 각각 출근/퇴근 로그에 반영되며, 순근무 차이(차이 열)와 상쇄하지 않습니다.',
  att_help_diff_types:
    '유형별 분 수는 조정 칸을 기준으로 합니다. 차이 열은 실제 근무 − 계획의 순증감(분)만 표시합니다.',
  att_adjust_help: '지각/연장에 표시된 수치 중 인정할 분을 입력 후 승인. 0=미인정',
